  // Estados da Central de Governança de Consentimento do Paciente & Smart Revocation (LGPD Art. 7/8/9/11/18 & CFP 006/2019)
  const [consentOverview, setConsentOverview] = useState<ConsentLedgerOverview | null>(null);
